/**
 * Mapa de Argentina por provincias (IGN – Instituto Geográfico Nacional, capa "provincia",
 * simplificada con mapshaper). Territorio continental + Islas Malvinas.
 * Proyección equirectangular con ancho corregido a la latitud -38.0°.
 */
export const MAPA = { ancho: 471.9, alto: 1000.0 };

const COS = 0.788011;
const MIN_X = -57.971587;
const MIN_Y = 21.789000;
const ESC = 30.058012;

/** Convierte latitud/longitud a coordenadas del mapa (mismo sistema que los trazos). */
export function proyectar(lat: number, lng: number) {
  return { x: (lng * COS - MIN_X) * ESC, y: (-lat - MIN_Y) * ESC };
}

